<script setup lang="ts">
import { computed, ref } from "vue";
import { onShow } from "@dcloudio/uni-app";
import EmptyState from "@/components/EmptyState.vue";
import { useAppTheme } from "@/composables/useAppTheme";
import { useWeatherStore } from "@/stores/weather";
import { useWardrobeStore } from "@/stores/wardrobe";
import type { CityCandidate } from "@/infrastructure/weather";
import { formatMessage, useI18n } from "@/i18n";

const store=useWeatherStore();const wardrobe=useWardrobeStore();const{themeClass}=useAppTheme();const{t}=useI18n();const query=ref("");
onShow(()=>wardrobe.hydrate());
const ageText=computed(()=>{if(!store.weather)return"";const minutes=Math.floor((Date.now()-store.weather.observedAt)/60000);return minutes<1?"刚刚更新":minutes<60?`${minutes}分钟前`:`${Math.floor(minutes/60)}小时前`;});
const advice=computed(()=>{const item=store.weather;if(!item)return"";const parts:string[]=[];if(item.temp<=5)parts.push("羽绒服与保暖内搭");else if(item.temp<=15)parts.push("长袖加外套");else if(item.temp<=25)parts.push("薄针织或轻盈裙装");else parts.push("短袖与透气材质");if((item.precipitationProbability||0)>=50)parts.push("记得带伞");if(item.wind>=20)parts.push("注意防风");return parts.join("，")+"。";});
const feelsLikeLabel=computed(()=>store.weather ? formatMessage("体感 {temperature}°", { temperature: store.weather.feelsLike ?? store.weather.temp }) : "");
function generate():void{if(!wardrobe.activeGarments.length){uni.navigateTo({url:"/pages/add/add?entry=weather"});return;}const context=encodeURIComponent(JSON.stringify({sceneId:"weekend",styleIds:[],preferredColors:[],avoidedColors:[],pinnedItemId:"",useWeather:true}));uni.navigateTo({url:`/pages/result/result?context=${context}`});}
function clearSearch(): void { query.value=""; store.clearCitySearch(); }
function chooseCity(city: CityCandidate): void { store.selectCity(city); query.value=""; }
</script>

<template>
  <view :class="['inner-page','weather-page',themeClass]">
    <text class="section-title block">今日天气</text>
    <view v-if="store.weather" class="weather-card" :class="{stale:store.stale}">
      <view class="weather-head"><view><text>{{ store.weather.city }}</text><text>{{ store.weather.condition }}</text></view><text>{{ store.weather.source==='example'?'示例':ageText }}</text></view>
      <view class="temperature"><text>{{ store.weather.temp }}°</text><view><text>{{ feelsLikeLabel }}</text><text v-if="store.weather.tempMin!==undefined">{{ store.weather.tempMin }}° / {{ store.weather.tempMax }}°</text></view></view>
      <view class="metrics"><view><text>降水</text><text>{{ store.weather.precipitationProbability ?? 0 }}%</text></view><view><text>湿度</text><text>{{ store.weather.humidity }}%</text></view><view><text>风速</text><text>{{ store.weather.wind }} km/h</text></view></view>
      <text v-if="store.stale" class="stale-label">天气已过期，请刷新</text>
    </view>
    <EmptyState v-else title="还没有天气" description="使用定位或搜索城市。" />

    <view class="source-actions"><button :loading="store.loading" aria-label="获取当前位置天气" @tap="store.useCurrentLocation">⌖ 当前位置</button><button aria-label="使用示例天气" @tap="store.useExample">示例天气</button></view>
    <view v-if="store.error" class="location-error"><view><text>{{ store.error }}</text><text>{{ store.locationFailure==='denied'?'可前往系统设置重新开启':store.locationFailure==='disabled'?'请先打开手机定位服务':'也可以搜索城市' }}</text></view><button v-if="store.locationFailure==='denied'||store.locationFailure==='disabled'" @tap="store.openSettings">去设置</button><button v-else @tap="store.useCurrentLocation">重试</button></view>
    <view class="search-helper"><text>搜索城市后，从候选地点中确认</text><text v-if="store.cityResults.length">{{ store.cityResults.length }} 个候选</text></view>
    <view class="city-search"><view class="search-input"><input v-model="query" class="text-field" aria-label="输入城市名称" placeholder="搜索城市，例如杭州" confirm-type="search" @confirm="store.findCities(query)" /><button v-if="query || store.cityResults.length" class="clear-search" aria-label="清除城市搜索" @tap="clearSearch">×</button></view><button aria-label="搜索城市天气" :loading="store.loading" @tap="store.findCities(query)">搜索</button></view>
    <view v-if="store.cityResults.length" class="city-results"><button v-for="city in store.cityResults" :key="`${city.latitude}-${city.longitude}`" @tap="chooseCity(city)"><view><text>{{ city.city }}</text><text>{{ city.detail || t('可用天气地点') }}</text></view><text>›</text></button></view>
    <view v-else-if="store.searchedCity && query" class="empty-results"><text>未找到匹配地点</text><text>请尝试城市名、区县名或英文名。</text><button @tap="clearSearch">清除搜索</button></view>
    <view v-if="store.weather" class="advice"><text>今日穿衣</text><text>{{ advice }}</text></view>
    <button class="primary-button recommend" :disabled="!store.weather" @tap="generate">按当前天气推荐</button>
  </view>
</template>

<style scoped lang="scss">
