button{min-width:98rpx;min-height:88rpx;margin:0;border:0;background:transparent;color:$focus;font-size:21rpx}.search-helper{display:flex;justify-content:space-between;margin:2rpx 4rpx 10rpx}.search-helper text{color:$muted;font-size:18rpx}.city-search{display:grid;grid-template-columns:1fr 112rpx;gap:12rpx}.search-input{display:flex;align-items:center;min-width:0;border:1rpx solid $line;border-radius:22rpx;background:$surface-solid}.search-input .text-field{flex:1;min-width:0;height:88rpx;padding-left:22rpx;border:0;background:transparent}.clear-search{display:flex;align-items:center;justify-content:center;flex:0 0 64rpx;width:64rpx;min-height:64rpx;margin:0 8rpx 0 0!important;padding:0!important;border:0!important;border-radius:999rpx!important;background:$lilac-soft!important;color:$muted!important;font-size:34rpx!important;line-height:1}.city-search>button{min-height:88rpx;margin:0;border:0;border-radius:22rpx;background:$ink;color:#fff;font-size:22rpx}.city-results{display:flex;flex-direction:column;margin-top:12rpx;overflow:hidden;border:1rpx solid $line;border-radius:22rpx;background:$surface-solid}.city-results button{display:grid;grid-template-columns:minmax(0,1fr) 32rpx;align-items:center;min-height:102rpx;margin:0;padding:14rpx 24rpx;border-bottom:1rpx solid $line;border-radius:0;background:transparent;color:$ink;text-align:left}.city-results button:last-child{border-bottom:0}.city-results button view text{display:block}.city-results button view text:first-child{font-size:24rpx;font-weight:760}.city-results button view text:last-child{margin-top:5rpx;color:$muted;font-size:19rpx}.city-results button>text{color:$muted-light;font-size:32rpx;text-align:right}.empty-results{display:grid;grid-template-columns:1fr auto;align-items:center;gap:8rpx;margin-top:12rpx;padding:18rpx 20rpx;border:1rpx solid $line;border-radius:22rpx;background:$surface-solid}.empty-results text{display:block}.empty-results text:first-child{color:$ink;font-size:22rpx;font-weight:700}.empty-results text:nth-child(2){margin-top:4rpx;color:$muted;font-size:18rpx}.empty-results button{min-height:64rpx;margin:0;padding:0 18rpx;border:0;border-radius:999rpx;background:$lilac-soft;color:$focus;font-size:19rpx}.advice{margin-top:22rpx;padding:26rpx;border:1rpx solid $line;border-radius:26rpx;background:$surface-solid}.advice text{display:block}.advice text:first-child{color:$lilac-deep;font-size:21rpx;font-weight:800}.advice text:last-child{margin-top:8rpx;color:$ink;font-size:24rpx;line-height:1.6}.recommend{width:100%;margin:22rpx 0}.recommend[disabled]{opacity:.5;box-shadow:none}
</style>
